<?php
namespace Tests\Unit; use PHPUnit\Framework\TestCase;
final class SharedDataGatewayContractTest extends TestCase { private string $root; protected function setUp():void{$this->root=dirname(__DIR__,2);} public function test_gateway_contract_and_states():void{$s=file_get_contents($this->root.'/src/Data/SharedDataResult.php');self::assertStringContainsString("['available','unavailable','unsupported','stale','failed']",$s);self::assertStringNotContainsString('Model $',$s);} public function test_provider_selection_and_missing_reader_are_explicit():void{$s=file_get_contents($this->root.'/src/Services/DefaultSharedDataGateway.php');self::assertStringContainsString('$this->resolver->resolve($s,$c)',$s);self::assertStringContainsString("'missing_reader'",$s);self::assertStringContainsString('NormalizedDataKeys::valid',$s);} public function test_internal_and_public_reads_are_separate():void{$s=file_get_contents($this->root.'/src/Contracts/SharedDataGateway.php');self::assertStringContainsString('public function read(', $s);self::assertStringContainsString('public function publicRead(', $s);self::assertStringContainsString('public function readMany(', $s);self::assertStringContainsString('public function supports(', $s);} }
